import subprocess

def run_new(args, inp=None):
    return subprocess.run(["python3","xz.py"]+args, input=inp, capture_output=True)
def run_exe(args, inp=None):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True)

def cmp(args, inp=None):
    a=run_new(args,inp)
    b=run_exe(args,inp)
    an=a.stderr.decode(errors='ignore').replace("xz.py","./executable")
    bn=b.stderr.decode(errors='ignore')
    print(args, "stderr new", repr(an), "orig", repr(bn), "match", an==bn, "code",a.returncode,b.returncode)
    print("stdout new", repr(a.stdout.decode(errors='ignore')[:200]), "orig", repr(b.stdout.decode(errors='ignore')[:200]))

cmp(["-q","--unknown"])
cmp(["-qq","--unknown"])
cmp(["--help"],None)
cmp(["--info-memory"])
PY
"}

{"command":"cat > /tmp/test_thread.py <<'PY'
import subprocess, sys

def run_sys(args, inp):
    return subprocess.run(["/usr/bin/xz"]+args, input=inp, capture_output=True)
def run_exe(args, inp):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True)
def run_new(args, inp):
    return subprocess.run(["python3","xz.py"]+args, input=inp, capture_output=True)

# test data varying size that may affect block splitting for multi-thread: larger data may split into multiple blocks
data=b"a"*500000  # 500KB
for thr in ["0","1","2"]:
    a=run_sys(["-6","-c","-T"+thr], data)
    b=run_exe(["-6","-c","-T"+thr], data)
    n=run_new(["-6","-c","-T"+thr], inp=data)
    print(f"thr {thr} sys {len(a.stdout)} exe {len(b.stdout)} new {len(n.stdout)} sys==exe {a.stdout==b.stdout} new==exe {n.stdout==b.stdout}")

# test with --block-size=1MiB threaded 2
data=b"a"*5000000
for thr in ["2"]:
    for bs in ["1MiB","100KiB"]:
        a=run_sys(["-6","-c","-T"+thr, "--block-size="+bs], data)
        b=run_exe(["-6","-c","-T"+thr, "--block-size="+bs], data)
        print(f"block {bs} thr {thr} sys {len(a.stdout)} exe {len(b.stdout)} same {a.stdout==b.stdout}")

PY
python3 /tmp/test_thread.py
