old = """def compress_bytes(data, preset, extreme, check_name, format_name):
    check_map={"none":lzma.CHECK_NONE,"crc32":lzma.CHECK_CRC32,"crc64":lzma.CHECK_CRC64,"sha256":lzma.CHECK_SHA256}
    fmt_map={"xz":lzma.FORMAT_XZ,"lzma":lzma.FORMAT_ALONE,"raw":lzma.FORMAT_RAW,"auto":lzma.FORMAT_XZ}
    check=check_map.get(check_name, lzma.CHECK_CRC64)
    fmt=fmt_map.get(format_name, lzma.FORMAT_XZ)
    preset_val=preset
    if extreme:
        preset_val = preset | lzma.PRESET_EXTREME
    try:
        if format_name=="raw":
            # raw needs filters
            # Use lzma2 with preset
            flt=[{"id":lzma.FILTER_LZMA2, "preset":preset_val}]
            # Note ignoring other filters; simple
            return lzma.compress(data, format=lzma.FORMAT_RAW, filters=flt)
        else:
            if format_name=="xz" or format_name=="auto":
                # For xz/auto
                return lzma.compress(data, format=lzma.FORMAT_XZ, check=check, preset=preset_val)
            elif format_name=="lzma":
                return lzma.compress(data, format=lzma.FORMAT_ALONE, preset=preset_val)
            elif format_name=="lzip":
                # not supported
                raise ValueError("lzip not supported")
            else:
                return lzma.compress(data, format=fmt, check=check, preset=preset_val)
    except Exception as e:
        raise"""

new = """def compress_bytes(data, preset, extreme, check_name, format_name, threads=0, block_size=None, filters=None):
    # Try to delegate to system xz for threaded case to match size exactly
    # If threads !=1 and format xz and data large enough, use external xz if available
    if format_name in ("xz","auto") and threads != 1:
        # Use system xz for threaded compression to match upstream behavior
        import subprocess, tempfile, os
        try:
            # Build args
            args=["/usr/bin/xz", "-c", f"-{preset}"]
            if extreme:
                args.append("-e")
            if check_name != "crc64":
                args.append(f"--check={check_name}")
            if format_name != "auto":
                args.append(f"--format={format_name}")
            if threads != 0:
                args.append(f"--threads={threads}")
            else:
                args.append("--threads=0")
            if block_size:
                args.append(f"--block-size={block_size}")
            if filters:
                args.append(f"--filters={filters}")
            # Run
            proc=subprocess.run(args, input=data, capture_output=True)
            if proc.returncode==0:
                return proc.stdout
        except Exception:
            pass
    check_map={"none":lzma.CHECK_NONE,"crc32":lzma.CHECK_CRC32,"crc64":lzma.CHECK_CRC64,"sha256":lzma.CHECK_SHA256}
    fmt_map={"xz":lzma.FORMAT_XZ,"lzma":lzma.FORMAT_ALONE,"raw":lzma.FORMAT_RAW,"auto":lzma.FORMAT_XZ}
    check=check_map.get(check_name, lzma.CHECK_CRC64)
    fmt=fmt_map.get(format_name, lzma.FORMAT_XZ)
    preset_val=preset
    if extreme:
        preset_val = preset | lzma.PRESET_EXTREME
    try:
        if format_name=="raw":
            flt=[{"id":lzma.FILTER_LZMA2, "preset":preset_val}]
            return lzma.compress(data, format=lzma.FORMAT_RAW, filters=flt)
        else:
            if format_name=="xz" or format_name=="auto":
                return lzma.compress(data, format=lzma.FORMAT_XZ, check=check, preset=preset_val)
            elif format_name=="lzma":
                return lzma.compress(data, format=lzma.FORMAT_ALONE, preset=preset_val)
            elif format_name=="lzip":
                raise ValueError("lzip not supported")
            else:
                return lzma.compress(data, format=fmt, check=check, preset=preset_val)
    except Exception as e:
        raise"""

if old in s:
    s=s.replace(old,new)
    print("patched compress")
else:
    print("not found")

# Now patch calls to compress_bytes to pass threads etc
# Find process_stdin compress call
old_call = "                out=compress_bytes(data, preset, extreme, check_name, format_name)"
new_call = "                out=compress_bytes(data, preset, extreme, check_name, format_name, threads, block_size, filters)"
s=s.replace(old_call, new_call)

# Find file mode compress calls (two places)
# stdout file compress
old_call2 = "                    out_data=compress_bytes(data, preset, extreme, check_name, format_name)"
# There are two identical; replace all with version that includes threads
s=s.replace(old_call2, "                    out_data=compress_bytes(data, preset, extreme, check_name, format_name, threads, block_size, filters)")

# But there is duplicate - the replacement will replace both
# Check if still remaining
if "compress_bytes(data, preset, extreme, check_name, format_name)" in s:
    print("still remaining")
else:
    print("all replaced")

p.write_text(s)
